// Algorithm
function canPlace(row, col) {
  for (let prior = 0; prior < col; prior++) {
    for (let other = 0; other < board.length; other++) {
      if (
        board[other][prior] === 1 &&
        (other === row || Math.abs(other - row) === col - prior)
