// Algorithm
function mergeSort(items, low, high) {
  if (high - low <= 1) return items;
  const middle = Math.floor((low + high) / 2);
  mergeSort(items, low, middle);
  mergeSort(items, middle, high);
  const left = items.slice(low, middle);
  const right = items.slice(middle, high);
  let i = 0;
  let j = 0;
  let k = low;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      items[k] = left[i];
      i++;
    } else {
      items[k] = right[j];
      j++;
    }
    k++;
  }
  while (i < left.length) {
    items[k] = left[i];
    i++;
    k++;
  }
  while (j < right.length) {
    items[k] = right[j];
    j++;
    k++;
  }
  return items;
}

