// Input
// Numeric array. Sorts in place using inclusive low/high bounds; returns the array.
const values = [4, 2, 4, 1, 3];

// Algorithm
function quickSort(items, low, high) {
  if (low >= high) return items;
  const pivot = items[high];
  let boundary = low;
  for (let scan = low; scan < high; scan++) {
    if (items[scan] < pivot) {
      [items[boundary], items[scan]] = [items[scan], items[boundary]];
      boundary++;
    }
  }
  [items[boundary], items[high]] = [items[high], items[boundary]];
  quickSort(items, low, boundary - 1);
  quickSort(items, boundary + 1, high);
  return items;
}

