// Input
// Returns the verified majority value, or null if none exists.
const numbers = [2, 2, 1, 1, 1, 2, 2];

// Algorithm
function majorityVote(items) {
  let candidate = null;
  let count = 0;
  for (let index = 0; index < items.length; index++) {
    if (count === 0) {
      candidate = items[index];
    }
    if (items[index] === candidate) {
      count += 1;
    } else {
      count -= 1;
    }
  }
  let verified = 0;
  for (let cursor = 0; cursor < items.length; cursor++) {
    if (items[cursor] === candidate) {
      verified += 1;
    }
  }
  return verified > items.length / 2 ? candidate : null;
}

